-- A fenced, expiring pause shared by every Worker and D1 writer.
CREATE TABLE platform_maintenance (
 singleton INTEGER PRIMARY KEY NOT NULL CHECK(singleton=1),
 owner TEXT,
 purpose TEXT CHECK(purpose IS NULL OR purpose='backup'),
 fence INTEGER NOT NULL CHECK(fence>=1 AND fence<=9007199254740991),
 expires_at INTEGER,
 CHECK((owner IS NULL AND purpose IS NULL AND expires_at IS NULL)
    OR (owner IS NOT NULL AND purpose IS NOT NULL AND expires_at IS NOT NULL))
) STRICT;

CREATE TRIGGER "cf_quiesce_accounting_accounts_insert" BEFORE INSERT ON "accounting_accounts" WHEN EXISTS(SELECT 1 FROM platform_maintenance WHERE singleton=1 AND owner IS NOT NULL AND expires_at>CAST(strftime('%s','now') AS INTEGER)*1000) BEGIN SELECT RAISE(ABORT,'erp_maintenance'); END;
CREATE TRIGGER "cf_quiesce_accounting_accounts_update" BEFORE UPDATE ON "accounting_accounts" WHEN EXISTS(SELECT 1 FROM platform_maintenance WHERE singleton=1 AND owner IS NOT NULL AND expires_at>CAST(strftime('%s','now') AS INTEGER)*1000) BEGIN SELECT RAISE(ABORT,'erp_maintenance'); END;
